function clamp(v, a, b){ return v < a ? a : (v > b ? b : v); }
function lerp(a, b, k){ return a + (b - a) * k; }
function smooth(k){ k = clamp(k, 0, 1); return k * k * (3 - 2 * k); }
function easeOut(k){ k = clamp(k, 0, 1); return 1 - Math.pow(1 - k, 3); }
function fract(x){ return x - Math.floor(x); }
function hash(n){ const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); }
function rgb(c, a){ const m = String(c).match(/\d+/g); return 'rgba(' + m[0] + ',' + m[1] + ',' + m[2] + ',' + a + ')'; }
function fitFont(size){ return 'bold ' + size + 'px Consolas,"Cascadia Mono","Microsoft YaHei",monospace'; }
function softFont(size){ return '600 ' + size + 'px "Segoe UI","Microsoft YaHei",sans-serif'; }

const glowCache = new Map();
function glowSprite(color){
  let c = glowCache.get(color);
  if(c) return c;
  c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d');
  const m = String(color).match(/\d+/g);
  const grad = g.createRadialGradient(64,64,0,64,64,64);
  grad.addColorStop(0, rgb(color, 0.85));
  grad.addColorStop(0.35, rgb(color, 0.32));
  grad.addColorStop(1, rgb(color, 0));
  g.fillStyle = grad; g.fillRect(0,0,128,128);
  glowCache.set(color, c);
  return c;
}
function drawGlow(x, y, r, color, alpha, comp){
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.globalCompositeOperation = comp || 'lighter';
  const s = glowSprite(color);
  const d = Math.max(2, r * 2);
  ctx.drawImage(s, x - d/2, y - d/2, d, d);
  ctx.restore();
}

