  for(const line of lines){
    if(!line || line[0] === '{') continue;
    const text = line.replace(/\[[^\]]*\]/g, '').trim();
    if(!text) continue;
    const re = /\[(\d+):(\d+(?:\.\d+)?)\]/g;
    let m;
    while((m = re.exec(line))){
      out.push({t: parseInt(m[1],10) * 60 + parseFloat(m[2]), text: text});
    }
  }
  out.sort((a,b) => a.t - b.t);
  return out;
})();

function lyricIndexAt(t){
  let idx = -1;
