  const grd = g.createRadialGradient(vignetteCanvas.width/2, vignetteCanvas.height/2, r*0.32, vignetteCanvas.width/2, vignetteCanvas.height/2, r);
  grd.addColorStop(0, 'rgba(0,0,0,0)');
