  drawGlow(cx + wob, cy, Math.min(W,H)*(0.13 + beatPulse*0.07), 'rgb(255,100,230)', a*0.30);
  drawGlow(cx - wob, cy, Math.min(W,H)*(0.10 + beatPulse*0.05), 'rgb(80,230,255)', a*0.28);
