  const oy = H*0.84;
  ctx.strokeStyle = rgb('rgb(90,255,210)', a*0.18); ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0, oy); ctx.lineTo(W, oy); ctx.stroke();
  ctx.beginPath();
  const amp = Math.min(W,H)*0.055 * (0.7 + bassLevel*2.2);
  for(let x = 0; x <= W; x += 5){
    const y = oy - Math.sin(x*0.022 - t*9)*amp*Math.exp(-Math.abs(x-cx)*0.0012);
    if(x === 0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.strokeStyle = rgb('rgb(100,255,215)', a*0.55); ctx.lineWidth = 1.6; ctx.stroke();
