  ctx.font = fitFont(15); ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';
  const flip = (Math.floor(t*2.4)%2 === 0);
  ctx.fillStyle = rgb('rgb(120,240,255)', a*0.8);
  ctx.fillText(flip ? 'AC → DC' : 'DC → AC', cx - W*0.30, H*0.20);
  ctx.fillStyle = rgb('rgb(255,130,220)', a*0.8);
  ctx.fillText(flip ? 'A.D → B.C' : 'B.C → A.D', cx + W*0.30, H*0.20);
  ctx.fillStyle = rgb('rgb(190,160,255)', a*0.55);
  ctx.fillText(dizzy > 0.5 ? '(⊙_☉)  so dizzy' : 'so dizzy so dizzy', cx, H*0.16);
  ctx.textAlign = 'left';
  ctx.restore();
}
