      }
    }
  }
  /* 进度 */
  const pp = clamp(t/15.9, 0, 1);
  ctx.fillStyle = rgb('rgb(30,70,55)', a*0.7); ctx.fillRect(tx+26, ty+th-36, tw-52, 6);
  ctx.fillStyle = rgb('rgb(80,255,190)', a); ctx.fillRect(tx+26, ty+th-36, (tw-52)*pp, 6);
  ctx.textAlign = 'right'; ctx.fillStyle = rgb('rgb(100,220,170)', a*0.65); ctx.font = fitFont(11);
  ctx.fillText('BOOT ' + (pp*100).toFixed(0) + '%', tx+tw-26, ty+th-47);
  /* 底部电压波形 */
  ctx.beginPath();
  const wy = H*0.82;
  for(let x = 0; x <= W; x += 6){
    const y = wy + Math.sin(x*0.025 - t*11) * 6 * (0.5 + beatPulse*0.7) + Math.sin(x*0.007 + t*3) * 5;
    if(x === 0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.strokeStyle = rgb('rgb(80,255,190)', a*0.30); ctx.lineWidth = 1.4; ctx.stroke();
  ctx.restore();
}

/* =========================================================
   SCENE 1 · 00:15.9 - 00:29.7  编译 / 生成世界
========================================================= */
const COMPILE_TITLE = 'world.execute(me);';
function renderCompile(t, a){
  ctx.save();
  bg('#01040d', a);
  const cx = W/2, cy = H/2 + H*0.02;
  const R = Math.min(W, H) * 0.31;
  const ry = t * 0.55, rx = t * 0.21;
  const cyr = Math.cos(ry), syr = Math.sin(ry), cxr = Math.cos(rx), sxr = Math.sin(rx);
  /* 星点 */
  ctx.fillStyle = rgb('rgb(120,160,255)', a*0.30);
  for(let i = 0; i < 60; i++){
    const x = hash(i*7.1)*W, y = hash(i*3.9)*H;
    ctx.fillRect(x, y, 2, 2);
  }
  /* 轨道粒子 */
  for(let i = 0; i < 74; i++){
    const an = t*(0.35 + 0.25*Math.sin(i*0.37)) + i*TAU/74;
    const rr = R*(0.45 + 0.48*Math.abs(Math.sin(i*0.53)));
    const px = cx + Math.cos(an)*rr, py = cy + Math.sin(an)*rr*0.42;
    ctx.fillStyle = rgb('rgb(90,200,255)', a*(0.30 + 0.25*Math.sin(t*3 + i)));
    ctx.beginPath(); ctx.arc(px, py, 1.6, 0, TAU); ctx.fill();
  }
  /* 旋转世界点云 */
  for(let i = 0; i < SPHERE.length; i++){
    const p = SPHERE[i];
    let x1 = p.x*cyr - p.z*syr;
    let z1 = p.x*syr + p.z*cyr;
    let y2 = p.y*cxr - z1*sxr;
    let z2 = p.y*sxr + z1*cxr;
    const depth = (z2 + 1) / 2;
    const px = cx + x1*R, py = cy + y2*R;
    ctx.fillStyle = rgb('rgb(140,245,255)', a*(0.10 + depth*0.55));
    ctx.beginPath(); ctx.arc(px, py, 0.8 + depth*2.3, 0, TAU); ctx.fill();
  }
  drawGlow(cx, cy, R*(0.38 + beatPulse*0.05), 'rgb(90,200,255)', a*0.30);
  /* 编译波纹 */
  const ring = t*0.9;
  for(let i = 0; i < 5; i++){
    const k = fract(ring + i/5);
    ctx.strokeStyle = rgb('rgb(110,220,255)', a*(1-k)*0.30);
    ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(cx, cy, R*(0.32 + k*0.75), 0, TAU); ctx.stroke();
  }
  /* 标题 */
  const titleSprite = textSprite(COMPILE_TITLE, fitFont(Math.min(56, W*0.055)), '#eafcff', 'rgb(90,200,255)');
  const th = Math.min(56, W*0.055);
  drawTextSprite(titleSprite, cx, H*0.16, th*(1 + beatPulse*0.03), a*0.96, 0);
  /* 编译进度 */
  const p = clamp(t/13.8, 0, 1);
  const bw = Math.min(560, W*0.72), bx = (W-bw)/2, by = H*0.80;
  ctx.fillStyle = rgb('rgb(20,45,75)', a*0.75); ctx.fillRect(bx, by, bw, 6);
  const grad = ctx.createLinearGradient(bx, 0, bx+bw, 0);
  grad.addColorStop(0, 'rgba(90,220,255,1)'); grad.addColorStop(1, 'rgba(255,110,210,1)');
  ctx.fillStyle = grad; ctx.fillRect(bx, by, bw*easeOut(p), 6);
  ctx.font = fitFont(12); ctx.fillStyle = rgb('rgb(160,210,255)', a*0.75); ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('> compiling universe ... ' + (p*100).toFixed(0) + '%', cx, by+24);
  ctx.textAlign = 'left';
  ctx.restore();
}

/* =========================================================
   SCENE 2 · 00:29.7 - 00:44.45  几何 / 数学情书
