function drawMathGrid(a){
  ctx.strokeStyle = rgb('rgb(90,150,170)', a*0.10);
  ctx.lineWidth = 1;
  ctx.beginPath();
  const gs = 52;
  for(let x = (W/2)%gs; x < W; x += gs){ ctx.moveTo(x,0); ctx.lineTo(x,H); }
  for(let y = (H/2)%gs; y < H; y += gs){ ctx.moveTo(0,y); ctx.lineTo(W,y); }
  ctx.stroke();
  ctx.strokeStyle = rgb('rgb(120,200,220)', a*0.20);
  ctx.beginPath(); ctx.moveTo(W/2,0); ctx.lineTo(W/2,H); ctx.moveTo(0,H/2); ctx.lineTo(W,H/2); ctx.stroke();
}
function drawPointsMotif(t, a){
  const cx = W/2, cy = H/2;
  for(let i = 0; i < 90; i++){
    const an = i*TAU/90, rr = Math.min(W,H)*(0.16 + hash(i*2.7)*0.22);
    const px = cx + Math.cos(an + t*0.5)*rr;
    const py = cy + Math.sin(an*1.7 + t*0.4)*rr;
    ctx.fillStyle = rgb('rgb(70,230,255)', a*(0.25 + hash(i)*0.55));
    ctx.beginPath(); ctx.arc(px, py, 1.4 + hash(i*5.1)*2.2, 0, TAU); ctx.fill();
    if(i % 9 === 0) drawGlow(px, py, 7, 'rgb(70,230,255)', a*0.25);
  }
  ctx.font = fitFont(14); ctx.fillStyle = rgb('rgb(150,235,255)', a*0.6); ctx.textAlign = 'center';
  ctx.fillText('{ x₁, x₂, x₃ ... x∞ }', cx, cy + Math.min(W,H)*0.34);
}
function drawCircleMotif(t, a){
  const cx = W/2, cy = H/2, R = Math.min(W,H)*0.26;
  const rr = R*(1 + Math.sin(t*2.2)*0.03 + beatPulse*0.05);
  ctx.strokeStyle = rgb('rgb(255,105,195)', a*0.85); ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.arc(cx, cy, rr, 0, TAU); ctx.stroke();
  drawGlow(cx, cy, rr, 'rgb(255,105,195)', a*0.12);
  for(let i = 0; i < 40; i++){
    const an = i/40*TAU;
    ctx.fillStyle = rgb('rgb(255,150,220)', a*0.8);
    ctx.beginPath(); ctx.arc(cx+Math.cos(an)*rr, cy+Math.sin(an)*rr, 2.2, 0, TAU); ctx.fill();
  }
  const an = t*1.1;
  ctx.strokeStyle = rgb('rgb(255,220,120)', a*0.85); ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx+Math.cos(an)*rr, cy+Math.sin(an)*rr); ctx.stroke();
  ctx.fillStyle = rgb('rgb(255,220,120)', a);
  ctx.beginPath(); ctx.arc(cx+Math.cos(an)*rr, cy+Math.sin(an)*rr, 5, 0, TAU); ctx.fill();
  ctx.font = fitFont(15); ctx.fillStyle = rgb('rgb(255,200,230)', a*0.8); ctx.textAlign = 'center';
  ctx.fillText('C = 2πr', cx, cy + R + 34);
}
function drawSineMotif(t, a){
  const cx = W/2, cy = H/2, amp = Math.min(W,H)*0.16;
  const x0 = cx - W*0.32, x1 = cx + W*0.32;
  ctx.beginPath();
  for(let x = x0; x <= x1; x += 6){
    const y = cy - Math.sin((x-x0)*0.018 - t*2.4)*amp;
    if(x === x0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.strokeStyle = rgb('rgb(255,215,90)', a*0.95); ctx.lineWidth = 3; ctx.stroke();
  drawGlow(cx, cy, Math.min(W,H)*0.34, 'rgb(255,180,60)', a*0.08);
  const px = cx + Math.sin(t*1.6)*W*0.2;
  const py = cy - Math.sin((px-x0)*0.018 - t*2.4)*amp;
  const slope = -Math.cos((px-x0)*0.018 - t*2.4)*amp*0.018;
  const dx = 90, dy = slope*dx;
  ctx.strokeStyle = rgb('rgb(120,255,220)', a*0.9); ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(px-dx, py-dy); ctx.lineTo(px+dx, py+dy); ctx.stroke();
  ctx.fillStyle = rgb('rgb(255,120,200)', a);
  ctx.beginPath(); ctx.arc(px, py, 6, 0, TAU); ctx.fill();
  ctx.font = fitFont(14); ctx.fillStyle = rgb('rgb(255,230,160)', a*0.75); ctx.textAlign = 'center';
  ctx.fillText('y = sin(x)  ·  tangent', cx, cy + Math.min(W,H)*0.31);
}
function drawInfinityMotif(t, a){
  const cx = W/2, cy = H/2, S = Math.min(W,H)*0.30;
  ctx.beginPath();
  for(let i = 0; i <= 140; i++){
    const th = i/140*TAU;
    const den = 1 + Math.sin(th)*Math.sin(th);
    const x = cx + Math.cos(th)/den*S;
    const y = cy + Math.sin(th)*Math.cos(th)/den*S*0.92;
    if(i === 0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.strokeStyle = rgb('rgb(255,105,220)', a*0.95); ctx.lineWidth = 3; ctx.stroke();
  drawGlow(cx, cy, S*0.9, 'rgb(255,90,200)', a*0.10);
  for(let k = 0; k < 2; k++){
    const tt = t*0.9 + k*Math.PI;
    const den = 1 + Math.sin(tt)*Math.sin(tt);
    const px = cx + Math.cos(tt)/den*S, py = cy + Math.sin(tt)*Math.cos(tt)/den*S*0.92;
    drawGlow(px, py, 12, 'rgb(255,170,230)', a*0.7);
  }
  ctx.font = fitFont(15); ctx.fillStyle = rgb('rgb(240,190,255)', a*0.75); ctx.textAlign = 'center';
  ctx.fillText('lim (me → you) = ∞', cx, cy + S*1.06);
}
function renderGeometry(t, a){
  ctx.save();
  bg('#03090c', a);
  drawMathGrid(a);
  const motifs = [
    {t0:0.0,  t1:3.7,  fn:drawPointsMotif},
    {t0:3.7,  t1:7.3,  fn:drawCircleMotif},
    {t0:7.3,  t1:11.0, fn:drawSineMotif},
    {t0:11.0, t1:14.75,fn:drawInfinityMotif}
  ];
  for(const m of motifs){
    let o = 0;
    if(t >= m.t0 && t < m.t1){
      o = smooth(clamp((t-m.t0)/0.65,0,1)) * smooth(clamp((m.t1-t)/0.65,0,1));
    }
    if(o > 0.01) m.fn(t, a*o);
  }
  ctx.font = fitFont(12); ctx.fillStyle = rgb('rgb(140,200,220)', a*0.45); ctx.textAlign = 'left';
  ctx.fillText('SECTION: GEOMETRY OF AFFECTION', 22, 28);
  ctx.textAlign = 'right';
  ctx.fillText('points → circle → sine → ∞', W-22, 28);
  ctx.textAlign = 'left';
  ctx.restore();
}

