function renderElectric(t, a){
  ctx.save();
  bg('#04010a', a);
  const cx = W/2, cy = H/2;
  const dizzy = smooth(clamp((t-4.8)/2.2, 0, 1));
  const wob = Math.sin(t*3.1)*dizzy*26;
  const spin = t*(0.22 + dizzy*0.75);
  const speed = 0.42 + beatPulse*0.28 + dizzy*0.16;
  for(let i = 0; i < 22; i++){
    const p = fract(i/22 + t*speed);
    const s = (0.06 + p*p*p*2.9) * Math.min(W,H) * 0.72;
    const hue = (t*70 + i*17) % 360;
    ctx.strokeStyle = 'hsla(' + hue.toFixed(0) + ',95%,64%,' + (a*(0.08 + p*0.42)) + ')';
    ctx.lineWidth = 1 + p*2.2;
    ctx.beginPath();
    const ang = spin + i*0.32;
    const ox = cx + Math.sin(t*2.2 + i*1.7)*dizzy*30;
    const oy = cy + Math.cos(t*2.6 + i*1.3)*dizzy*24;
    for(let k = 0; k <= 4; k++){
      const an = ang + k*TAU/4;
      const px = ox + Math.cos(an)*s, py = oy + Math.sin(an)*s;
      if(k === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.closePath(); ctx.stroke();
  }
  /* 中心光 */
  drawGlow(cx + wob, cy, Math.min(W,H)*(0.13 + beatPulse*0.07), 'rgb(255,100,230)', a*0.30);
  drawGlow(cx - wob, cy, Math.min(W,H)*(0.10 + beatPulse*0.05), 'rgb(80,230,255)', a*0.28);
  /* 示波器 */
  const oy = H*0.84;
  ctx.strokeStyle = rgb('rgb(90,255,210)', a*0.18); ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(0, oy); ctx.lineTo(W, oy); ctx.stroke();
  ctx.beginPath();
  const amp = Math.min(W,H)*0.055 * (0.7 + bassLevel*2.2);
  for(let x = 0; x <= W; x += 5){
    const y = oy - Math.sin(x*0.022 - t*9)*amp*Math.exp(-Math.abs(x-cx)*0.0012);
    if(x === 0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.strokeStyle = rgb('rgb(100,255,215)', a*0.55); ctx.lineWidth = 1.6; ctx.stroke();
  /* 符号 */
  ctx.font = fitFont(15); ctx.textBaseline = 'middle';
  ctx.textAlign = 'center';
  const flip = (Math.floor(t*2.4)%2 === 0);
  ctx.fillStyle = rgb('rgb(120,240,255)', a*0.8);
  ctx.fillText(flip ? 'AC → DC' : 'DC → AC', cx - W*0.30, H*0.20);
  ctx.fillStyle = rgb('rgb(255,130,220)', a*0.8);
  ctx.fillText(flip ? 'A.D → B.C' : 'B.C → A.D', cx + W*0.30, H*0.20);
  ctx.fillStyle = rgb('rgb(190,160,255)', a*0.55);
  ctx.fillText(dizzy > 0.5 ? '(⊙_☉)  so dizzy' : 'so dizzy so dizzy', cx, H*0.16);
  ctx.textAlign = 'left';
  ctx.restore();
}
