function heartScale(){ return Math.min(W, H) * 0.42; }
function renderNeural(t, a){
  ctx.save();
  bg('#08020f', a);
  const cx = W/2, cy = H/2, S = heartScale();
  const hb = Math.max(beatPulse, Math.pow(Math.max(0, Math.sin(t*13.4 - 1.57)), 20));
  const scale = 1 + hb*0.045 + Math.sin(t*0.9)*0.008;
  const pulseA = a*(0.75 + beatPulse*0.25);
  /* 神经连线 */
  ctx.lineWidth = 1;
  for(let e = 0; e < HEART_EDGES.length; e++){
    const edge = HEART_EDGES[e], A = HEART_NODES[edge.a], B = HEART_NODES[edge.b];
    ctx.strokeStyle = rgb('rgb(160,90,255)', a*(0.06 + 0.05*Math.sin(t*2 + e*0.7)));
    ctx.beginPath();
    ctx.moveTo(cx + A.x*S*scale, cy + A.y*S*scale);
    ctx.lineTo(cx + B.x*S*scale, cy + B.y*S*scale);
    ctx.stroke();
  }
  /* 突触脉冲 */
  for(let i = 0; i < 14; i++){
    const edge = HEART_EDGES[(i*7 + Math.floor(t*2)) % HEART_EDGES.length];
    const A = HEART_NODES[edge.a], B = HEART_NODES[edge.b];
    const k = fract(t*(0.45 + hash(i*3.3)*0.5) + i*0.13);
    const px = cx + lerp(A.x, B.x, k)*S*scale;
    const py = cy + lerp(A.y, B.y, k)*S*scale;
    drawGlow(px, py, 4 + k*5, 'rgb(255,120,230)', pulseA*0.55);
  }
  /* 心形节点 */
  for(let i = 0; i < HEART_NODES.length; i++){
    const p = HEART_NODES[i];
    const x = cx + p.x*S*scale, y = cy + p.y*S*scale;
    const rr = 1.6 + 1.6*Math.sin(t*3 + i*0.6) + hb*2.2;
    ctx.fillStyle = rgb('rgb(255,150,230)', pulseA*0.8);
    ctx.beginPath(); ctx.arc(x, y, Math.max(0.6, rr), 0, TAU); ctx.fill();
    if(i % 6 === 0) drawGlow(x, y, 8 + hb*9, 'rgb(255,110,210)', pulseA*0.35);
  }
  /* 中心核心 */
  drawGlow(cx, cy, S*(0.24 + hb*0.10), 'rgb(255,100,200)', pulseA*0.45);
  drawGlow(cx, cy, S*0.11, 'rgb(255,240,250)', pulseA*0.75);
  /* 模拟牢笼 */
  const cage = smooth(clamp((t-10.6)/3.4, 0, 1));
  if(cage > 0.01){
    const cw = S*1.35, ch = S*1.15;
    ctx.strokeStyle = rgb('rgb(100,220,255)', a*cage*0.42);
    ctx.lineWidth = 1.4;
    ctx.strokeRect(cx-cw/2, cy-ch/2, cw, ch);
    for(let i = 1; i < 5; i++){
      const k = i/5;
      ctx.beginPath(); ctx.moveTo(lerp(cx-cw/2, cx+cw/2, k), cy-ch/2); ctx.lineTo(lerp(cx-cw/2, cx+cw/2, k), cy+ch/2); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(cx-cw/2, lerp(cy-ch/2, cy+ch/2, k)); ctx.lineTo(cx+cw/2, lerp(cy-ch/2, cy+ch/2, k)); ctx.stroke();
    }
    ctx.fillStyle = rgb('rgb(100,220,255)', a*cage*0.7); ctx.font = fitFont(12);
    ctx.textAlign = 'center'; ctx.fillText('SIMULATION', cx, cy-ch/2-14);
    ctx.textAlign = 'left';
  }
  ctx.restore();
}

