    for(let j = 0; j < 9; j++){
      const y = (off + j*24 + H + 160) % (H+160) - 80;
      if(y < -20 || y > H+20) continue;
      const ch = ERR_GLYPHS[(hash(i*13.1 + j*3.7 + Math.floor(t*9))*ERR_GLYPHS.length)|0];
