function renderRebuild(t, a){
  ctx.save();
  bg('#050417', a);
  const cx = W/2, cy = H/2, S = Math.min(W,H)*0.40;
  const gather = easeOut(clamp((t-0.2)/8.0, 0, 1));
  const bt = Math.max(beatPulse, Math.pow(Math.max(0, Math.sin(t*12.8 - 1.4)), 18));
  /* 汇聚粒子 */
  for(let i = 0; i < 130; i++){
    const th = i/130*TAU;
    const target = HEART_PTS[Math.floor(i*140/130) % 140];
    const startR = Math.min(W,H)*(0.52 + hash(i*3.3)*0.30);
    const sx = cx + Math.cos(th + hash(i)*0.6)*startR;
    const sy = cy + Math.sin(th*1.7 + hash(i+30)*0.8)*startR*0.6;
    const x = lerp(sx, cx + target.x*S*(1 + bt*0.03), gather);
    const y = lerp(sy, cy + target.y*S*(1 + bt*0.03), gather);
    const col = mix3('rgb(110,210,255)', 'rgb(255,110,210)', gather);
    ctx.fillStyle = rgb(col, a*(0.25 + 0.45*gather));
    ctx.beginPath(); ctx.arc(x, y, 1.2 + gather*1.8 + bt*1.6, 0, TAU); ctx.fill();
    if(i % 17 === 0) drawGlow(x, y, 7 + gather*9, col, a*(0.18 + gather*0.2));
  }
  /* 心形轮廓逐渐出现 */
  if(gather > 0.45){
    ctx.strokeStyle = rgb(mix3('rgb(110,210,255)','rgb(255,110,210)',gather), a*(gather-0.45)*1.4);
    ctx.lineWidth = 2.4;
    pathHeartShape(S*(1 + bt*0.04), 0, cx, cy); ctx.stroke();
  }
  drawGlow(cx, cy, S*(0.14 + gather*0.16), 'rgb(255,130,220)', a*(0.25 + gather*0.3));
  /* 轨道环 */
  for(let k = 0; k < 2; k++){
    const rr = S*(0.62 + k*0.18) * (1 + bt*0.03);
    ctx.strokeStyle = rgb(k ? 'rgb(255,110,210)' : 'rgb(110,210,255)', a*(0.15 + gather*0.15));
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.arc(cx, cy, rr, t*(0.3 + k*0.4), t*(0.3 + k*0.4)+TAU*0.72); ctx.stroke();
