    ctx.scale(1, Math.max(0.008, sy));
    ctx.translate(-cx, -cy);
    ctx.font = fitFont(Math.min(22, W*0.026));
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    if(t < 0.7){
      ctx.fillStyle = rgb('rgb(255,90,150)', a*0.95);
      ctx.fillText('> EXECUTION', cx, cy-8);
    } else if(t < 1.6){
      ctx.fillStyle = rgb('rgb(130,240,190)', a*0.8);
      ctx.fillText('> process exited with code 0', cx, cy-8);
    } else if(t < 2.6){
      ctx.fillStyle = rgb('rgb(120,180,255)', a*0.75);
      ctx.fillText('> shutdown -h now', cx, cy-8);
    } else {
      ctx.fillStyle = rgb('rgb(255,255,255)', a*0.6);
      ctx.fillText('█', cx, cy-8);
