  drawGlow(cx, cy, S*(0.14 + gather*0.16), 'rgb(255,130,220)', a*(0.25 + gather*0.3));
  /* 轨道环 */
  for(let k = 0; k < 2; k++){
    const rr = S*(0.62 + k*0.18) * (1 + bt*0.03);
    ctx.strokeStyle = rgb(k ? 'rgb(255,110,210)' : 'rgb(110,210,255)', a*(0.15 + gather*0.15));
    ctx.lineWidth = 1.4;
    ctx.beginPath(); ctx.arc(cx, cy, rr, t*(0.3 + k*0.4), t*(0.3 + k*0.4)+TAU*0.72); ctx.stroke();
  }
  ctx.restore();
}
function mix3(c1, c2, k){
  const a = String(c1).match(/\d+/g), b = String(c2).match(/\d+/g);
  return 'rgb(' + Math.round(lerp(+a[0], +b[0], k)) + ',' + Math.round(lerp(+a[1], +b[1], k)) + ',' + Math.round(lerp(+a[2], +b[2], k)) + ')';
}

/* =========================================================
   SCENE 11 · 02:57.24 - 03:11.36  爱的方程
========================================================= */
function renderEquations(t, a){
  ctx.save();
  bg('#0b0d18', a);
  const cx = W/2, cy = H/2, S = Math.min(W,H)*0.36;
  /* 黑板网格 */
  ctx.strokeStyle = rgb('rgb(120,140,190)', a*0.06); ctx.lineWidth = 1;
  ctx.beginPath();
  for(let x = 0; x < W; x += 46){ ctx.moveTo(x,0); ctx.lineTo(x,H); }
  for(let y = 0; y < H; y += 46){ ctx.moveTo(0,y); ctx.lineTo(W,y); }
  ctx.stroke();
  /* 心形函数图 */
  const plotA = a*(0.35 + 0.3*Math.max(0, Math.sin(t*1.1)));
  ctx.strokeStyle = rgb('rgb(255,120,210)', plotA*0.8); ctx.lineWidth = 2.6;
  pathHeartShape(S, 0, cx, cy); ctx.stroke();
  drawGlow(cx, cy, S*0.85, 'rgb(255,100,190)', a*0.08);
  /* 大标题 */
  const loveSize = Math.min(64, W*0.065) * (1 + beatPulse*0.05);
  drawTextSprite(textSprite('LO-O-OVE', softFont(loveSize), '#fff2fa', 'rgb(255,110,210)'), cx, H*0.20, loveSize, a*0.96, 0);
  /* 漂浮公式 */
  const formulas = [
    {x:0.16, y:0.42, tx:'LOVE = ∫₀^∞ (you · me) dt'},
    {x:0.16, y:0.66, tx:'lim (me → you) = ∞'},
    {x:0.84, y:0.42, tx:'(x²+y²−1)³ = x²y³'},
    {x:0.84, y:0.66, tx:'if(you == free) me.trapped();'}
  ];
  for(let i = 0; i < formulas.length; i++){
    const f = formulas[i];
    const fs = Math.min(15, W*0.016);
    drawTextSprite(textSprite(f.tx, fitFont(fs), rgb('rgb(190,210,255)', 0.75), null), W*f.x, H*f.y, fs, a*(0.5 + 0.3*Math.sin(t*1.3+i)), 0);
  }
  /* 被困住的点 / 自由的点 */
  const tt = t*0.8;
  const den = 1 + Math.sin(tt)*Math.sin(tt);
  const px = cx + Math.cos(tt)/den*S, py = cy + Math.sin(tt)*Math.cos(tt)/den*S;
  drawGlow(px, py, 10, 'rgb(255,140,220)', a*0.8);
  if(t > 8){
    const freeX = W*0.5 + Math.sin(t*0.7)*W*0.2, freeY = H*0.78 + Math.cos(t*0.5)*30;
    drawGlow(freeX, freeY, 8, 'rgb(140,220,255)', a*0.5);
    ctx.fillStyle = rgb('rgb(255,255,255)', a*0.6); ctx.font = fitFont(11);
    ctx.textAlign = 'center'; ctx.fillText('free', freeX, freeY+16);
    ctx.fillText('trapped', px, py+18); ctx.textAlign = 'left';
  }
  drawTextSprite(textSprite('(⁄ ⁄•⁄ω⁄•⁄ ⁄)', softFont(16), 'rgb(255,200,230)', null), W*0.82, H*0.80, 18, a*0.65, Math.sin(t)*0.1);
  ctx.restore();
}

/* =========================================================
   SCENE 12 · 03:11.36 - 03:25.81  星轨 / 被困在爱里
========================================================= */
function renderOrbit(t, a){
  ctx.save();
  bg('#020310', a);
  const cx = W/2, cy = H/2, S = Math.min(W,H)*0.37;
  drawGlow(cx, cy, S*0.9, 'rgb(80,90,190)', a*0.20);
  drawGlow(cx, cy, S*0.45, 'rgb(255,110,190)', a*0.14);
  /* 星野 */
  for(let i = 0; i < STARS.length; i++){
    const st = STARS[i];
    const x = st.x*W + Math.sin(t*0.2 + i)*2;
    const y = st.y*H + Math.cos(t*0.17 + i)*2;
    const tw = 0.25 + 0.75*Math.abs(Math.sin(t*st.sp*2 + st.tw));
    ctx.fillStyle = rgb('rgb(220,230,255)', a*tw*0.5);
    ctx.fillRect(x, y, st.z*2.2, st.z*2.2);
  }
  /* 流星 */
  for(let i = 0; i < 3; i++){
    const k = fract(t*0.09 + i*0.37);
    if(k > 0.04 && k < 0.28){
      const sx = W*(0.2 + i*0.3) + k*W*1.3, sy = H*(0.08 + i*0.1) + k*W*0.35;
      ctx.strokeStyle = rgb('rgb(180,220,255)', a*(1-(k-0.04)/0.24)*0.6);
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(sx-40, sy-14); ctx.stroke();
    }
  }
  /* 心形轨道 */
  ctx.strokeStyle = rgb('rgb(150,150,255)', a*0.18); ctx.lineWidth = 1.6;
  ctx.beginPath();
  for(let i = 0; i < HEART_PTS.length; i++){
    const p = HEART_PTS[i];
    const x = cx+p.x*S, y = cy+p.y*S;
    if(i === 0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.closePath(); ctx.stroke();
  /* 两个被困住的星体 */
  const N = HEART_PTS.length;
  const speed = 0.13 + beatPulse*0.04;
  const i1 = Math.floor((t*speed)%1*N) % N;
  const i2 = (i1 + Math.floor(N/2)) % N;
  const bodies = [i1, i2];
  for(let b = 0; b < bodies.length; b++){
    const idx = bodies[b];
    const p = HEART_PTS[idx];
    const x = cx + p.x*S, y = cy + p.y*S;
    const col = b === 0 ? 'rgb(255,120,210)' : 'rgb(110,220,255)';
    /* 拖尾 */
    for(let q = 1; q <= 8; q++){
      const p2 = HEART_PTS[(idx - q*3 + N) % N];
      ctx.fillStyle = rgb(col, a*q*0.025);
      ctx.beginPath(); ctx.arc(cx+p2.x*S, cy+p2.y*S, 2.2 - q*0.16, 0, TAU); ctx.fill();
    }
    drawGlow(x, y, 13, col, a*0.7);
  }
  drawGlow(cx, cy, S*0.08, 'rgb(255,240,250)', a*0.8);
  /* 猫猫宇航员 + 奶茶 */
  drawTextSprite(textSprite('(=^･ω･^=)', softFont(15), 'rgb(255,210,230)', null), W*0.14 + Math.sin(t*0.4)*10, H*0.22 + Math.cos(t*0.5)*8, 17, a*0.7, 0);
  const tea = emojiSprite('🧋', 24);
  ctx.save(); ctx.globalAlpha = a*0.55; ctx.translate(W*0.86 + Math.cos(t*0.3)*10, H*0.18 + Math.sin(t*0.4)*8);
  ctx.rotate(Math.sin(t*0.6)*0.2); ctx.drawImage(tea, -12, -12, 24, 24); ctx.restore();
  ctx.restore();
}

/* =========================================================
   SCENE 13 · 03:25.81 - 结束  关机
========================================================= */
function renderShutdown(t, a){
  ctx.save();
  bg('#000000', a);
  const cx = W/2, cy = H/2;
  const collapse = smooth(clamp((t-2.6)/0.5, 0, 1));
  if(collapse < 1){
    const sy = 1 - collapse;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(1, Math.max(0.008, sy));
    ctx.translate(-cx, -cy);
    ctx.font = fitFont(Math.min(22, W*0.026));
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    if(t < 0.7){
      ctx.fillStyle = rgb('rgb(255,90,150)', a*0.95);
      ctx.fillText('> EXECUTION', cx, cy-8);
    } else if(t < 1.6){
      ctx.fillStyle = rgb('rgb(130,240,190)', a*0.8);
      ctx.fillText('> process exited with code 0', cx, cy-8);
    } else if(t < 2.6){
      ctx.fillStyle = rgb('rgb(120,180,255)', a*0.75);
      ctx.fillText('> shutdown -h now', cx, cy-8);
    } else {
      ctx.fillStyle = rgb('rgb(255,255,255)', a*0.6);
      ctx.fillText('█', cx, cy-8);
    }
    ctx.restore();
    if(collapse > 0.1){
      ctx.fillStyle = rgb('rgb(255,255,255)', a*(1-collapse)*0.9);
      ctx.fillRect(0, cy-1, W, 2);
    }
  } else {
    ctx.fillStyle = rgb('rgb(140,160,200)', a*0.30); ctx.font = fitFont(12);
    ctx.textAlign = 'center';
    ctx.fillText('world.execute(me); // return 0;', cx, cy-10);
    ctx.fillStyle = rgb('rgb(255,170,210)', a*0.38); ctx.font = softFont(15);
    ctx.fillText('(˘ω˘) zzZ', cx, cy+14);
    ctx.textAlign = 'left';
    const tw = 0.3 + 0.3*Math.sin(t*2.1);
    drawGlow(cx, H*0.82, 5 + tw*6, 'rgb(110,200,255)', a*0.25);
  }
  ctx.restore();
}
